row s8-os-release post - '[ -f /etc/os-release ] && [ ! -L /etc/os-release ]'
row s8-panthor-link post - 'test ! -e /etc/systemd/system/multi-user.target.wants/h96-panthor-setup.service && test ! -L /etc/systemd/system/multi-user.target.wants/h96-panthor-setup.service'
row s8-panthor-unit post - 'test ! -e /etc/systemd/system/h96-panthor-setup.service && test ! -e /usr/lib/systemd/system/h96-panthor-setup.service'
row s8-mpv post - '! dpkg -s mpv >/dev/null 2>&1'
row s8-h96-installed post - '[ "$(dpkg-query -W -f '"'"'${db:Status-Abbrev}\n'"'"' h96-audio h96-base h96-boot h96-desktop h96-gaming h96-media h96-net h96-tools 2>/dev/null | grep -c '"'"'^ii '"'"')" = 8 ]'
row s8-video-payload post - 'P=$(sed -n '"'"'s/^PAYLOAD=//p'"'"' /usr/lib/h96/h96-video-setup.sh) && [ "$P" = /usr/lib/h96/video ] && grep -qx '"'"'TAR="$PAYLOAD/h96-video-stack.tar.gz"'"'"' /usr/lib/h96/h96-video-setup.sh && dpkg -S "$P/h96-video-stack.tar.gz" | grep -q '"'"'^h96-media:'"'"' && tar tzf "$P/h96-video-stack.tar.gz" | grep -qx usr/bin/mpv'
row s8-mali-udev post - 'for f in 50-mali.rules 99-mali.rules 99-mali-gdm.rules; do test -f /etc/udev/rules.d/$f || exit 1; done; grep -qx '"'"'SUBSYSTEM=="drm", KERNEL=="renderD\*", MODE="0666", GROUP="render"'"'"' /etc/udev/rules.d/99-mali-gdm.rules'
row s8-no-prompt post - 'ls "$F5_LOG"/install-*.txt >/dev/null && ! grep -q '"'"'Configuration file'"'"' "$F5_LOG"/install-*.txt'
row s8-dpkg-v post - '[ -z "$(dpkg -V h96-audio h96-base h96-boot h96-desktop h96-gaming h96-media h96-net h96-tools steam-arm-setup 2>&1)" ]'
row s8-dpkg-audit post - '[ -z "$(dpkg --audit 2>&1)" ]'
